import React from "react";
import { Link } from "react-router-dom";

const services = [
  {
    title: "Website Design",
    text: "Custom layouts designed around your brand and your customers, not a generic template.",
    points: ["UI/UX design", "Brand-matched visuals", "Mobile-first layouts"],
  },
  {
    title: "Web Development",
    text: "Fast, reliable websites built with modern tools like the MERN stack (MongoDB, Express, React, Node.js).",
    points: ["Custom frontend & backend", "Database-driven features", "API integrations"],
  },
  {
    title: "E-Commerce",
    text: "Online stores that make it easy for customers to browse, buy, and come back.",
    points: ["Product catalogs", "Secure checkout", "Order & inventory tracking"],
  },
  {
    title: "SEO & Performance",
    text: "Sites tuned to load quickly and rank well, so the traffic you earn actually finds you.",
    points: ["Page speed optimization", "On-page SEO", "Analytics setup"],
  },
  {
    title: "Maintenance & Support",
    text: "Ongoing updates, monitoring, and fixes so your site keeps running smoothly after launch.",
    points: ["Security updates", "Content updates", "Uptime monitoring"],
  },
  {
    title: "Hosting & Deployment",
    text: "We handle setup and deployment so your site is fast, secure, and easy to manage.",
    points: ["Domain & hosting setup", "SSL & security", "CI/CD deployment"],
  },
];

const Services = () => {
  return (
    <>
      <section className="page-hero">
        <div className="page-hero-inner">
          <p className="eyebrow-plain">Services</p>
          <h1>Everything you need to launch and grow online.</h1>
          <p className="hero-sub">
            From first sketch to a live, working website — and the support to
            keep it running after that.
          </p>
        </div>
      </section>

      <section className="section">
        <div className="services-grid">
          {services.map((s) => (
            <div className="service-card" key={s.title}>
              <h3>{s.title}</h3>
              <p>{s.text}</p>
              <ul>
                {s.points.map((p) => (
                  <li key={p}>{p}</li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </section>

      <section className="section cta-band">
        <div className="cta-band-inner">
          <div>
            <h2>Not sure what you need?</h2>
            <p>Tell us about your business — we'll suggest the right fit.</p>
          </div>
          <Link to="/contact" className="btn btn-primary btn-on-dark">
            Talk to us
          </Link>
        </div>
      </section>
    </>
  );
};

export default Services;
